flowchart TB
  AL@{ svc: "Amazon CloudWatch", label: "CloudWatch alarm<br/>状態が変わる<br/>例: ALARM" }
  SNS@{ svc: "Amazon SNS", label: "SNS トピック" }
  SUB["購読者<br/>人もアプリも"]
  LA@{ svc: "AWS Lambda", label: "Lambda 関数<br/>独自の処理" }
  AL -- "通知" --> SNS
  SNS --> SUB
  AL -- "呼び出す" --> LA

flowchart TB
  AL@{ svc: "Amazon CloudWatch", label: "CloudWatch<br/>metric alarm" }
  EAS@{ svc: "Amazon EC2 Auto Scaling", label: "EC2 Auto Scaling<br/>Auto Scaling group<br/>の EC2" }
  AAS["Application Auto Scaling<br/>ほかのリソースの例:<br/>ECS サービス・<br/>DynamoDB の表"]
  AL -- "scaling policy" --> EAS
  AL -- "scaling policy" --> AAS

flowchart TB
  S3@{ svc: "Amazon S3", label: "S3 バケット<br/>決まった種類の<br/>イベント" }
  LA@{ svc: "AWS Lambda", label: "Lambda 関数<br/>独自のコード" }
  NT["届き方<br/>少なくとも 1 回<br/>1 回だけとは限らない<br/>ふつう数秒、1 分以上も"]
  S3 -- "イベント通知" --> LA
  LA ~~~ NT
